ing // Factura A, Factura B, Factura C...\n  invoiceNumber          String\n  customerName           String\n  counterpartyCuit       String?\n  netAmount              Decimal  @db.Decimal(18, 2)\n  ivaAmount              Decimal  @db.Decimal(18, 2)\n  totalAmount            Decimal  @db.Decimal(18, 2)\n  isExempt               Boolean  @default(false) // Soporte para Ingresos Exentos (Monotributo/Exenciones)\n  // Criterio 2026-07-16: categoría de la venta (Bienes / Servicios / MueblesYUtiles) y si computa\n  // en los ingresos de Ganancias (No computable = excluida del cálculo de la DDJJ).\n  saleCategory           String   @default(\"Bienes\")\n  isComputable           Boolean  @default(true)\n  // Trazabilidad de la importación desde el libro fiscal mensual (módulo IVA). Nulos = carga manual.\n  importSource           String? // 'MONTHLY_LEDGER' si vino del módulo mensual; null si se cargó a mano.\n  sourceFiscalDocumentId String? // Comprobante mensual de origen, para auditar registro anual ↔ mensual.\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n\n  @@index([taxReturnId])\n  @@index([taxReturnId, invoiceNumber])\n  @@index([counterpartyCuit])\n  @@index([taxReturnId, importSource])\n}\n\nmodel PurchaseInvoice {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  date                   DateTime\n  invoiceType            String\n  invoiceNumber          String\n  vendorName             String\n  counterpartyCuit       String?\n  netAmount              Decimal  @db.Decimal(18, 2)\n  ivaAmount              Decimal  @db.Decimal(18, 2)\n  totalAmount            Decimal  @db.Decimal(18, 2)\n  isDeductible           Boolean  @default(true) // Indica si es deducible en ganancias\n  isExempt               Boolean  @default(false) // Gastos exentos / no gravados\n  expenseType            String? // Combustibles, Alquileres, PapelerÃ­a, etc.\n  // Trazabilidad de la importación desde el libro fiscal mensual (módulo IVA). Nulos = carga manual.\n  importSource           String? // 'MONTHLY_LEDGER' si vino del módulo mensual; null si se cargó a mano.\n  sourceFiscalDocumentId String? // Comprobante mensual de origen, para auditar registro anual ↔ mensual.\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n\n  @@index([taxReturnId])\n  @@index([taxReturnId, invoiceNumber])\n  @@index([counterpartyCuit])\n  @@index([taxReturnId, importSource])\n}\n\nmodel FixedAsset {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  name             String // e.g., \"Automotor 1\", \"Inmueble Calle X\"\n  type             String // Rodado, Inmueble, Equipamiento, etc.\n  purchaseDate     DateTime\n  originalCost     Decimal  @db.Decimal(18, 2)\n  usefulLife       Int // Vida Ãºtil total en aÃ±os (e.g., 5, 50)\n  yearsElapsed     Int // AÃ±os transcurridos al cierre actual\n  originalIva      Decimal  @default(0) @db.Decimal(18, 2)\n  customReexpIndex Decimal  @default(1.0) @db.Decimal(12, 6) // Coeficiente IPC correspondiente\n  isRetired        Boolean  @default(false)\n\n  // Datos de AmortizaciÃ³n Calculada (se almacenan para auditorÃ­a y persistencia)\n  annualDepreciationHist Decimal  @db.Decimal(18, 2)\n  annualDepreciationAdj  Decimal  @db.Decimal(18, 2)\n  residualValueHist      Decimal  @db.Decimal(18, 2)\n  residualValueAdj       Decimal  @db.Decimal(18, 2)\n  bajaLossHist           Decimal  @default(0) @db.Decimal(18, 2)\n  bajaLossAdj            Decimal  @default(0) @db.Decimal(18, 2)\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n\n  @@index([taxReturnId])\n  @@index([taxReturnId, isRetired])\n}\n\nmodel InventoryValue {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  concept      String // Bienes de Cambio, Materia Prima, etc.\n  initialStock Decimal @db.Decimal(18, 2) // ValuaciÃ³n al inicio (PerÃ­odo anterior)\n  finalStock   Decimal @db.Decimal(18, 2) // ValuaciÃ³n impositiva al cierre\n\n  @@index([taxReturnId])\n}\n\nmodel BankAccountBalance {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  bankName              String\n  cuitBank              String?\n  accountNumber         String\n  accountType           String // Caja de Ahorro, Cuenta Corriente, etc.\n  currency              String  @default(\"ARS\") // ARS, USD, EUR\n  nominalBalanceInitial Decimal @db.Decimal(18, 2)\n  nominalBalanceFinal   Decimal @db.Decimal(18, 2)\n  tcInitial             Decimal @default(1.0) @db.Decimal(12, 4) // Tipo de Cambio compra BNA al inicio\n  tcFinal               Decimal @default(1.0) @db.Decimal(12, 4) // Tipo de Cambio compra BNA al cierre\n  balanceInitialArs     Decimal @db.Decimal(18, 2)\n  balanceFinalArs       Decimal @db.Decimal(18, 2)\n  interests             Decimal @default(0) @db.Decimal(18, 2) // Intereses devengados\n\n  @@index([taxReturnId])\n}\n\nmodel CashHolding {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  currency        String  @default(\"ARS\")\n  nominalInitial  Decimal @db.Decimal(18, 2)\n  nominalFinal    Decimal @db.Decimal(18, 2)\n  tcFinal         Decimal @default(1.0) @db.Decimal(12, 4)\n  totalInitialArs Decimal @db.Decimal(18, 2)\n  totalFinalArs   Decimal @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\nmodel ReceivableDebt {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  type           String // Comercial (Clientes), Fiscal (Saldos TÃ©cnicos), Financiero (PrÃ©stamos)\n  description    String // e.g., \"Clientes de GestiÃ³n\", \"IVA Saldo TÃ©cnico\", \"RetenciÃ³n Impuesto\"\n  balanceInitial Decimal @db.Decimal(18, 2)\n  balanceFinal   Decimal @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\nmodel PayableDebt {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  type           String // Proveedores, Acreedores Varios, PrÃ©stamos, Tarjetas\n  description    String\n  balanceInitial Decimal @db.Decimal(18, 2)\n  balanceFinal   Decimal @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\nmodel TaxWithholding {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  cuitAgent            String?\n  agentName            String\n  taxCode              String // Ganancias, IVA, Bienes Personales...\n  taxDescription       String\n  regimeCode           String?\n  regimeDescription    String?\n  date                 DateTime\n  certificateNumber    String\n  operationDescription String?\n  amount               Decimal  @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\n// ==========================================\n// 6. PATRIMONIO PERSONAL Y JUSTIFICACIÃ“N (JVP)\n// ==========================================\n\nmodel PersonalAsset {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  description  String // e.g., \"Inmueble 1\", \"Rodado Automotor\", \"Dinero en Efectivo Personal\"\n  type         String // Inmueble, Rodado, DepÃ³sitos, Efectivo, Acciones\n  valueInitial Decimal @db.Decimal(18, 2)\n  valueFinal   Decimal @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\nmodel PersonalLiability {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  description  String // e.g., \"PrÃ©stamo Hipotecario Personal\", \"Tarjetas de CrÃ©dito\"\n  valueInitial Decimal @db.Decimal(18, 2)\n  valueFinal   Decimal @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\nmodel PatrimonialJustification {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  concept String // e.g., \"Ganancia exenta\", \"AmortizaciÃ³n de bienes de uso\", \"Herencia\"\n  column  Int // 1 = Columna I (Erogaciones/PN final), 2 = Columna II (PN inicial/Justifica)\n  amount  Decimal @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\nmodel GeneralDeduction {\n  id          String    @id @default(uuid())\n  taxReturnId String    @unique\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  autonomos                 Decimal  @default(0) @db.Decimal(18, 2)\n  servicioDomestico         Decimal  @default(0) @db.Decimal(18, 2)\n  seguroVida                Decimal  @default(0) @db.Decimal(18, 2)\n  seguroRetiro              Decimal  @default(0) @db.Decimal(18, 2)\n  gastosSepelio             Decimal  @default(0) @db.Decimal(18, 2)\n  interesesHipoteca         Decimal  @default(0) @db.Decimal(18, 2)\n  gastosEducativos          Decimal  @default(0) @db.Decimal(18, 2)\n  alquilerCasaHabitacion    Decimal  @default(0) @db.Decimal(18, 2)\n  deduccionLocadorLocatario Decimal  @default(0) @db.Decimal(18, 2)\n  donaciones                Decimal  @default(0) @db.Decimal(18, 2)\n  medicosAsistencial        Decimal  @default(0) @db.Decimal(18, 2)\n  honorariosMedicos         Decimal  @default(0) @db.Decimal(18, 2)\n  createdAt                 DateTime @default(now())\n  updatedAt                 DateTime @updatedAt\n}\n\nmodel PersonalDeduction {\n  id          String    @id @default(uuid())\n  taxReturnId String    @unique\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  tieneConyuge               Boolean  @default(false)\n  cantidadHijos              Int      @default(0)\n  cantidadHijosIncapacitados Int      @default(0)\n  tipoDeduccionEspecial      String   @default(\"Ninguna\")\n  esJubiladoOchoHaberes      Boolean  @default(false)\n  createdAt                  DateTime @default(now())\n  updatedAt                  DateTime @updatedAt\n}\n\n// ==========================================\n// 7. AJUSTE POR INFLACIÃ“N IMPOSITIVO (AXI)\n// ==========================================\n\nmodel AxiStaticItem {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  concept          String // e.g., \"Activo Total de Inicio\", \"Inmuebles y Obras en Curso\", \"Retenciones y Anticipos\"\n  section          String // ACTIVO_TOTAL, BIEN_NO_COMPUTABLE, AJUSTE_ACTIVO, PASIVO_TOTAL\n  categoryKey      String?\n  amount           Decimal  @db.Decimal(18, 2)\n  totalAmount      Decimal  @default(0) @db.Decimal(18, 2)\n  computableAmount Decimal  @default(0) @db.Decimal(18, 2)\n  isComputable     Boolean  @default(false)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([taxReturnId])\n  @@index([taxReturnId, section])\n  @@index([taxReturnId, categoryKey])\n}\n\nmodel AxiDynamicItem {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  concept     String // e.g., \"Retiro de socios\", \"Dividendos\", \"Aumentos de capital\"\n  type        String // AJUSTE_POSITIVO, AJUSTE_NEGATIVO\n  date        DateTime?\n  amount      Decimal   @db.Decimal(18, 2)\n  coef        Decimal   @db.Decimal(12, 6)\n  factor      Decimal   @db.Decimal(6, 4) // e.g., -1 o 1 para la fÃ³rmula\n  computedAxi Decimal   @db.Decimal(18, 2)\n\n  @@index([taxReturnId])\n}\n\n// ==========================================\n// 8. RESULTADOS INTERMEDIOS Y EJECUCIONES DEL MOTOR\n// ==========================================\n\nmodel CalculationRun {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  runDate    DateTime @default(now())\n  executorId String?\n\n  // Resultados Consolidados de LiquidaciÃ³n\n  resultThirdCategory              Decimal @db.Decimal(18, 2) // Resultado de Tercera CategorÃ­a\n  resultTotalNet                   Decimal @db.Decimal(18, 2) // Total Ganancia Bruta (todas las cat)\n  totalGeneralDeductions           Decimal @db.Decimal(18, 2)\n  impositiveResultBeforeQuebrantos Decimal @db.Decimal(18, 2)\n  quebrantosApplied                Decimal @db.Decimal(18, 2)\n  impositiveResultNet              Decimal @db.Decimal(18, 2)\n  totalPersonalDeductions          Decimal @db.Decimal(18, 2)\n  taxableIncome                    Decimal @db.Decimal(18, 2) // Ganancia Neta Sujeta a Impuesto\n  taxDetermined                    Decimal @db.Decimal(18, 2) // Impuesto Determinado (Art 94)\n  totalPaymentsOnAccount           Decimal @db.Decimal(18, 2) // Retenciones + Percepciones + Anticipos\n  finalBalance                     Decimal @db.Decimal(18, 2) // Impuesto a pagar o saldo a favor\n\n  // JustificaciÃ³n Patrimonial (ConciliaciÃ³n)\n  computedConsumo   Decimal @db.Decimal(18, 2) // Consumo obtenido por diferencia\n  justificationDiff Decimal @default(0) @db.Decimal(18, 2) // Diferencia de cuadre (debe ser 0)\n\n  // Ajuste por InflaciÃ³n\n  axiStaticResult  Decimal @db.Decimal(18, 2)\n  axiDynamicResult Decimal @db.Decimal(18, 2)\n  axiNetAdjustment Decimal @db.Decimal(18, 2) // Sumatoria AXI neto imputado en el ejercicio\n\n  // Datos TÃ©cnicos / AuditorÃ­a\n  variablesSnapshot String? @db.LongText // Almacenamiento JSON con las variables intermedias\n  hasErrors         Boolean @default(false)\n  errorMessages     String? @db.Text\n\n  @@index([taxReturnId])\n}\n\nmodel Attachment {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  fileName      String\n  fileSize      Int\n  fileExtension String\n  mimeType      String\n  storageType   String          @default(\"DB\") // DB, EXTERNAL\n  securePath    String? // Ruta lÃ³gica protegida si se usa almacenamiento externo\n  fileHash      String // MD5/SHA256 para validaciÃ³n de integridad\n  uploadedById  String?\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n  blob          AttachmentBlob?\n\n  @@index([taxReturnId])\n  @@index([fileHash])\n}\n\nmodel AttachmentBlob {\n  id           String     @id @default(uuid())\n  attachmentId String     @unique\n  attachment   Attachment @relation(fields: [attachmentId], references: [id], onDelete: Cascade)\n  content      Bytes      @db.LongBlob\n  createdAt    DateTime   @default(now())\n}\n\nmodel ImportBatch {\n  id          String    @id @default(uuid())\n  taxReturnId String\n  taxReturn   TaxReturn @relation(fields: [taxReturnId], references: [id], onDelete: Cascade)\n\n  kind             String // sales, purchases, withholdings\n  source           String    @default(\"AFIP\")\n  periodFrom       DateTime?\n  periodTo         DateTime?\n  totalFiles       Int       @default(0)\n  totalRecords     Int       @default(0)\n  acceptedRecords  Int       @default(0)\n  duplicateRecords Int       @default(0)\n  rejectedRecords  Int       @default(0)\n  status           String    @default(\"Procesado\")\n  notes            String?   @db.Text\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  files ImportFile[]\n\n  @@index([taxReturnId])\n  @@index([kind])\n  @@index([createdAt])\n}\n\nmodel ImportFile {\n  id            String      @id @default(uuid())\n  importBatchId String\n  importBatch   ImportBatch @relation(fields: [importBatchId], references: [id], onDelete: Cascade)\n\n  fileName         String\n  fileHash         String\n  fileSize         Int      @default(0)\n  mimeType         String?\n  periodMonth      Int?\n  periodYear       Int?\n  totalRecords     Int      @default(0)\n  acceptedRecords  Int      @default(0)\n  duplicateRecords Int      @default(0)\n  rejectedRecords  Int      @default(0)\n  status           String   @default(\"Procesado\")\n  errors           String?  @db.Text\n  createdAt        DateTime @default(now())\n\n  @@index([importBatchId])\n  @@index([fileHash])\n  @@index([periodYear, periodMonth])\n}\n\nmodel AuditLog {\n  id     String  @id @default(uuid())\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  action     String // CREATE, UPDATE, DELETE, CLOSE, REOPEN, RECTIFY\n  entityType String // TaxReturn, SalesInvoice, FixedAsset, etc.\n  entityId   String?\n  clientCuit String?\n  clientName String?\n  fiscalYear Int?\n  details    String?  @db.Text\n  createdAt  DateTime @default(now())\n\n  @@index([userId])\n  @@index([createdAt])\n}\n\n// Configuracion del backup automatico local (arquitectura elegida 2026-07-19: carpeta\n// sincronizada de Google Drive en la PC del usuario; el runner scripts/backup-runner.mjs\n// lee esta fila y ejecuta el backup cuando corresponde).\nmodel BackupConfig {\n  id              String    @id @default(uuid())\n  enabled         Boolean   @default(false)\n  destinationPath String // Carpeta de destino (ej. G:\\Mi unidad\\Backups JABA)\n  frequency       String    @default(\"DAILY\") // DAILY | WEEKLY\n  hour            Int       @default(21) // 0-23, hora local de la PC\n  weekday         Int       @default(6) // 0=domingo..6=sabado (solo WEEKLY)\n  retentionDays   Int       @default(30)\n  lastRunAt       DateTime?\n  lastRunStatus   String? // OK | ERROR: detalle\n  lastRunFile     String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n}\n",
